body {
  margin: 0;
  background: #eef1f5;
  color: #101828;
  font-family: Inter, Arial, sans-serif;
}

.page {
  padding: 18px;
  box-sizing: border-box;
}

.print-button {
  display: block;
  margin: 0 auto 14px;
  width: 160px;
  height: 40px;
  border: 0;
  border-radius: 7px;
  background: #101828;
  color: #fff;
  font-weight: 800;
  cursor: pointer;
}

.document {
  width: 210mm;
  min-height: 297mm;
  background: #fff;
  margin: 0 auto;
  padding: 16mm;
  box-sizing: border-box;
  box-shadow: 0 18px 50px rgba(15, 23, 42, 0.16);
}

.top-line {
  height: 6px;
  margin: -16mm -16mm 14mm;
  background: linear-gradient(90deg, #101828, #2563eb, #0f766e);
}

.header {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  padding-bottom: 16px;
  border-bottom: 1px solid #d0d5dd;
}

.brand {
  display: flex;
  gap: 14px;
  align-items: flex-start;
}

.logo {
  width: 86px;
  max-height: 68px;
  object-fit: contain;
}

h1 {
  margin: 0 0 5px;
  font-size: 25px;
}

p {
  margin: 2px 0;
  color: #667085;
  font-size: 12px;
}

.doc-title {
  text-align: right;
  min-width: 220px;
}

.doc-title span {
  display: inline-block;
  padding: 6px 10px;
  background: #eff6ff;
  color: #1d4ed8;
  border: 1px solid #bfdbfe;
  font-size: 11px;
  text-transform: uppercase;
  font-weight: 900;
}

.doc-title strong {
  display: block;
  margin-top: 10px;
  font-size: 25px;
}

.doc-title small {
  display: block;
  margin-top: 4px;
  color: #667085;
}

.parties {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
  margin: 16px 0;
}

.parties > div {
  border: 1px solid #d0d5dd;
  padding: 11px;
}

.parties span {
  display: block;
  margin-bottom: 6px;
  color: #667085;
  font-size: 10px;
  text-transform: uppercase;
  font-weight: 900;
}

.parties strong {
  display: block;
  font-size: 15px;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th {
  background: #f2f4f7;
  color: #344054;
  font-size: 11px;
  text-align: left;
  padding: 9px 8px;
  border-bottom: 1px solid #d0d5dd;
}

td {
  padding: 9px 8px;
  font-size: 12px;
  border-bottom: 1px solid #eaecf0;
  vertical-align: top;
}

td div {
  margin-top: 2px;
  color: #667085;
  font-size: 11px;
}

.right {
  text-align: right;
  white-space: nowrap;
}

.bottom {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 18px;
  margin-top: 18px;
  align-items: start;
}

.qr {
  width: 112px;
  height: 112px;
}

.barcode {
  margin-top: 14px;
}

.summary {
  border: 1px solid #d0d5dd;
}

.summary div {
  display: flex;
  justify-content: space-between;
  padding: 10px 12px;
  border-bottom: 1px solid #d0d5dd;
  font-size: 13px;
}

.summary div:last-child {
  border-bottom: 0;
}

.summary .total {
  background: #101828;
  color: #fff;
  font-size: 16px;
  font-weight: 900;
}

.tax-table {
  margin-top: 18px;
}

.signatures {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 90px;
  margin-top: 56px;
}

.signatures div {
  border-top: 1px solid #101828;
  text-align: center;
  padding-top: 7px;
  font-size: 12px;
  font-weight: 700;
}

.empty {
  background: white;
  padding: 28px;
  text-align: center;
  color: #667085;
}

@media print {
  body {
    background: white;
  }
  .page {
    padding: 0;
  }
  .print-button {
    display: none;
  }
  .document {
    width: 210mm;
    min-height: 297mm;
    margin: 0;
    padding: 14mm;
    box-shadow: none;
  }
  .top-line {
    margin: -14mm -14mm 14mm;
  }
}

