          <div>
            <span>Customer</span>
            <strong>{header.partnerName || header.customerName || "-"}</strong>
            <p>
              {[header.partnerAddress, header.partnerPostalCode, header.partnerCity]
                .filter(Boolean)
                .join(", ")}
            </p>
            <p>{header.partnerTaxNumber ? `Tax No: ${header.partnerTaxNumber}` : ""}</p>
          </div>

          <div>
            <span>Document info</span>
            <p>Status: <b>{header.status || "-"}</b></p>
            <p>Warehouse: <b>{header.warehouseName || "-"}</b></p>
            <p>Payment: <b>{header.paymentMethod || "-"}</b></p>
            <p>Currency: <b>{header.currencyCode || "EUR"}</b></p>
          </div>
        </div>

        <table>
          <thead>
            <tr>
              <th>Item</th>
              <th className="right">Qty</th>
              <th className="right">Price</th>
              <th className="right">Tax</th>
              <th className="right">Total</th>
            </tr>
          </thead>
          <tbody>
            {items.map((item, index) => (
              <tr key={index}>
                <td>
                  <b>{item.productCode || ""}</b>
                  <div>{item.description || item.productName || item.product || "Item"}</div>
                </td>
                <td className="right">{qty(item.quantity)}</td>
                <td className="right">{money(item.unitPrice)}</td>
                <td className="right">{money(item.taxAmount)}</td>
                <td className="right">{money(item.lineTotal)}</td>
              </tr>
            ))}
          </tbody>
        </table>

        <div className="bottom">
          <div>
            {qr && <img className="qr" src={qr} />}
            <div className="barcode">
              <Barcode value={header.documentNumber} />
            </div>
          </div>

          <div className="summary">
            <div><span>Subtotal</span><b>{money(header.subtotalAmount)} {header.currencyCode || "EUR"}</b></div>
            <div><span>Discount</span><b>{money(header.discountAmount)} {header.currencyCode || "EUR"}</b></div>
            <div><span>Tax</span><b>{money(header.taxAmount)} {header.currencyCode || "EUR"}</b></div>
            <div className="total"><span>Total</span><b>{money(header.totalAmount)} {header.currencyCode || "EUR"}</b></div>
          </div>
        </div>

        {taxes.length > 0 && (
          <table className="tax-table">
            <thead>
              <tr>
                <th>Tax Rate</th>
                <th className="right">Taxable</th>
                <th className="right">Tax</th>
                <th className="right">Total</th>
              </tr>
            </thead>
            <tbody>
              {taxes.map((tax, index) => (
                <tr key={index}>
                  <td>{money(tax.taxRate)}%</td>
                  <td className="right">{money(tax.taxableAmount)}</td>
                  <td className="right">{money(tax.taxAmount)}</td>
                  <td className="right">{money(tax.totalAmount)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}

        <div className="signatures">
          <div>Issued by</div>
          <div>Received by</div>
        </div>
      </div>
    </div>
  );
}

function render() {
  ReactDOM.render(<App />, document.getElementById("root"));
}

appsmith.onReady(() => {
  render();
  appsmith.onModelChange(render);
});
